                op = self.tokens[self.current]
                self.current += 1
                if op == '+':
                    result += self.term()
                else:
                    result -= self.term()
            return result

        def term(self):
            result = self.factor()
            while self.current < len(self.tokens) and self.tokens[self.current] in ('*', '/'):
                op = self.tokens[self.current]
                self.current += 1
                if op == '*':
                    result *= self.factor()
                else:
                    result /= self.factor()
            return result

        def factor(self):
            token = self.tokens[self.current]
            if token == '(':
